// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testRegression_property() public {
        c.SetMinSum(10);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        vm.deal(address(0x1), 10);
        vm.prank(address(0x1));
        c.Deposit{value: 10}();

        vm.prank(address(0x1));
        try c.Collect(10) {
            assertTrue(c.balances(address(0x1)) == 0);
        } catch {
            assertTrue(false);
        }
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
